import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { ComponentStore } from "../../core/ecs/ComponentStore";
import { InputIntentComponent, PlayerStatsComponent, TetherComponent, TraversalStateComponent, TransformComponent } from "../../core/ecs/Components";
import { EntityRefs } from "../../core/ecs/EntityRefs";
import { CommandBus } from "../../core/commands/CommandBus";
import { EventBroker } from "../../core/events/EventBroker";
import { GameEvent } from "../../core/events/GameEvents";
import { SetKinematicVelocityCommand, SetRopeAttachedCommand, SetRopeMaxLengthCommand, ApplyImpulseCommand } from "../../physics/commands/PhysicsCommands";

export class PlayerMovementSystem implements ISystem {
  readonly phase = SystemPhase.Intents;
  private spaceWasPressed = false;
  private detachWasPressed = false;

  constructor(
    private refs: EntityRefs,
    private inputs: ComponentStore<InputIntentComponent>,
    private stats: ComponentStore<PlayerStatsComponent>,
    private tethers: ComponentStore<TetherComponent>,
    private traversal: ComponentStore<TraversalStateComponent>,
    private transforms: ComponentStore<TransformComponent>,
    private commands: CommandBus,
    private broker: EventBroker
  ) {}

  public update(dt: number): void {
    const input = this.inputs.get(this.refs.player);
    const stats = this.stats.get(this.refs.player);
    const tether = this.tethers.get(this.refs.player);
    const trav = this.traversal.get(this.refs.player);
    const playerTrans = this.transforms.get(this.refs.player);
    if (!input || !stats || !tether || !trav || !playerTrans) return;

    if (input.detach && !this.detachWasPressed) {
      if (!tether.isAttached) {
        let anchorY = 28.0; 
        const playerX = playerTrans.x;
        const playerY = playerTrans.y;

        if (playerX >= -15.0 && playerX <= -7.0 && playerY < 11.5) {
          anchorY = 11.5;
        } else if (playerX >= 7.0 && playerX <= 15.0 && playerY < 17.5) {
          anchorY = 17.5;
        }

        const anchorTrans = this.transforms.get(this.refs.anchor);
        if (anchorTrans) {
          anchorTrans.x = playerX;
          anchorTrans.y = anchorY;
          anchorTrans.z = 0;
        }

        tether.anchorX = playerX;
        tether.anchorY = anchorY;
        tether.anchorZ = 0;

        const dx = playerTrans.x - playerX;
        const dy = playerTrans.y - anchorY;
        tether.maxLength = Math.max(stats.minRope, Math.sqrt(dx * dx + dy * dy));
        tether.isAttached = true;

        this.commands.dispatch<SetRopeAttachedCommand>({ type: "SET_ROPE_ATTACHED", attached: true });
        this.commands.dispatch<SetRopeMaxLengthCommand>({ type: "SET_ROPE_MAX_LENGTH", length: tether.maxLength });
        this.broker.publish(GameEvent.CAMERA_SHAKE_TRIGGERED, { amplitude: 0.15, duration: 0.15 });
      } else {
        tether.isAttached = false;
        this.commands.dispatch<SetRopeAttachedCommand>({ type: "SET_ROPE_ATTACHED", attached: false });
      }
    }
    this.detachWasPressed = input.detach;

    if (input.jump && !this.spaceWasPressed) {
      if (trav.state === "WALL_SLIDING") {
        const chargeMultiplier = 1.0 + trav.charge * 1.5;
        const launchX = trav.wallNormalX * 15.0 * chargeMultiplier;
        const launchY = 11.0 * chargeMultiplier;

        trav.charge = 0.0;

        this.commands.dispatch<ApplyImpulseCommand>({
          type: "APPLY_IMPULSE",
          entityId: this.refs.player,
          x: launchX,
          y: launchY,
          z: 0
        });

        const shakeAmplitude = 0.2 + (chargeMultiplier - 1.0) * 0.4;
        this.broker.publish(GameEvent.CAMERA_SHAKE_TRIGGERED, { amplitude: shakeAmplitude, duration: 0.25 });
      }
    }
    this.spaceWasPressed = input.jump;

    if (tether.isAttached) {
      if (input.y > 0) tether.maxLength = Math.max(stats.minRope, tether.maxLength - stats.climbSpeed * dt);
      else if (input.y < 0) tether.maxLength = Math.min(stats.maxRope, tether.maxLength + stats.climbSpeed * dt);

      this.commands.dispatch<SetRopeMaxLengthCommand>({ type: "SET_ROPE_MAX_LENGTH", length: tether.maxLength });
      this.commands.dispatch<SetKinematicVelocityCommand>({ type: "SET_KINEMATIC_VELOCITY", entityId: this.refs.player, x: input.x * stats.swingForce, y: 0, z: 0 });
    } else {
      this.commands.dispatch<SetKinematicVelocityCommand>({ type: "SET_KINEMATIC_VELOCITY", entityId: this.refs.player, x: input.x * stats.moveSpeed, y: 0, z: 0 });
    }

    const speed = Math.sqrt(tether.dynamicVelX * tether.dynamicVelX + tether.dynamicVelY * tether.dynamicVelY);
    this.broker.publish(GameEvent.PLAYER_VELOCITY_CHANGED, {
      velocity: speed,
      maxVelocity: 30.0
    });
  }
}

src/gameplay/systems/RopeVisualizerSyste:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { IVisualRegistry } from "../../contracts/IVisualRegistry";
import { ComponentStore } from "../../core/ecs/ComponentStore";
import { TransformComponent, TetherComponent } from "../../core/ecs/Components";
import { EntityRefs } from "../../core/ecs/EntityRefs";
import * as BABYLON from "@babylonjs/core";

export class RopeVisualizerSystem implements ISystem {
  readonly phase = SystemPhase.RenderSync;
  private ropeMesh: BABYLON.Mesh | null = null;
  private ropeMat: BABYLON.StandardMaterial | null = null;
  private segments = 24;
  private points: BABYLON.Vector3[] = [];
  private scratchAnchor = new BABYLON.Vector3();
  private scratchPlayer = new BABYLON.Vector3();
  private scratchLerp = new BABYLON.Vector3();

  constructor(
    private refs: EntityRefs,
    private transforms: ComponentStore<TransformComponent>,
    private tethers: ComponentStore<TetherComponent>,
    private visualRegistry: IVisualRegistry
  ) {
    for (let i = 0; i <= this.segments; i++) {
      this.points.push(new BABYLON.Vector3(0, 0, 0));
    }
  }

  public init(): void {
    const scene = this.visualRegistry.getScene();
    if (!scene) return;

    this.ropeMat = new BABYLON.StandardMaterial("ropeMat", scene);
    this.ropeMat.diffuseColor = new BABYLON.Color3(0.8, 0.9, 1.0);
    this.ropeMat.emissiveColor = new BABYLON.Color3(0.2, 0.4, 0.6);
    this.ropeMat.specularColor = new BABYLON.Color3(0.5, 0.5, 0.5);

    this.ropeMesh = BABYLON.MeshBuilder.CreateTube("tetherTube", {
      path: this.points,
      radius: 0.08,
      tessellation: 8,
      cap: BABYLON.Mesh.NO_CAP,
      updatable: true
    }, scene);
    this.ropeMesh.material = this.ropeMat;
  }

  public render(alpha: number): void {
    if (!this.ropeMesh || !this.ropeMat) return;
    const pTrans = this.transforms.get(this.refs.player);
    const aTrans = this.transforms.get(this.refs.anchor);
    const tether = this.tethers.get(this.refs.player);
    if (!pTrans || !aTrans || !tether) return;

    if (!tether.isAttached) {
      this.ropeMesh.setEnabled(false);
      return;
    }
    this.ropeMesh.setEnabled(true);

    const px = pTrans.prevX + (pTrans.x - pTrans.prevX) * alpha;
    const py = pTrans.prevY + (pTrans.y - pTrans.prevY) * alpha;
    this.scratchPlayer.set(px, py, 0);
    this.scratchAnchor.set(aTrans.x, aTrans.y, aTrans.z);

    const clampedTension = Math.max(0, Math.min(1, tether.currentLength / tether.maxLength));
    const sagFactor = (1.0 - clampedTension) * 2.5;
    const applySag = clampedTension < 0.95;

    for (let i = 0; i <= this.segments; i++) {
      const ratio = i / this.segments;
      BABYLON.Vector3.LerpToRef(this.scratchAnchor, this.scratchPlayer, ratio, this.scratchLerp);
      if (applySag) {
        this.scratchLerp.y -= Math.sin(ratio * Math.PI) * sagFactor;
      }
      const targetPoint = this.points[i];
      targetPoint.x = this.scratchLerp.x;
      targetPoint.y = this.scratchLerp.y;
      targetPoint.z = this.scratchLerp.z;
    }

    const radius = 0.12 - (clampedTension * 0.07);
    this.ropeMesh = BABYLON.MeshBuilder.CreateTube("tetherTube", {
      path: this.points,
      radius: radius,
      tessellation: 8,
      cap: BABYLON.Mesh.NO_CAP,
      instance: this.ropeMesh
    });

    if (clampedTension > 0.8) {
      const t = (clampedTension - 0.8) / 0.2;
      this.ropeMat.emissiveColor.r = 0.2 + t * 0.8;
      this.ropeMat.emissiveColor.g = 0.4 - t * 0.3;
      this.ropeMat.emissiveColor.b = 0.6 - t * 0.5;
    } else {
      this.ropeMat.emissiveColor.r = 0.2;
      this.ropeMat.emissiveColor.g = 0.4;
      this.ropeMat.emissiveColor.b = 0.6;
    }
  }

  public dispose(): void {
    if (this.ropeMesh) this.ropeMesh.dispose();
    if (this.ropeMat) this.ropeMat.dispose();
  }
}

src/gameplay/systems/WardenBrainSystem.t:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { ComponentStore } from "../../core/ecs/ComponentStore";
import { WardenAIComponent, TransformComponent, WardenTraversalComponent, HealthComponent } from "../../core/ecs/Components";
import { EntityRefs } from "../../core/ecs/EntityRefs";
import { IWardenState, WardenStateType, AIContext } from "../states/IWardenState";
import { WardenDormantState } from "../states/WardenDormantState";
import { WardenHuntingState } from "../states/WardenHuntingState";
import { WardenChargePrepState } from "../states/WardenChargePrepState";
import { WardenChargeAttackState } from "../states/WardenChargeAttackState";
import { WardenRecoveryState } from "../states/WardenRecoveryState";
import { WardenFakeDeathState } from "../states/WardenFakeDeathState";
import { WardenFinalPhaseState } from "../states/WardenFinalPhaseState";
import { EventBroker } from "../../core/events/EventBroker";
import { GameEvent } from "../../core/events/GameEvents";
import { CommandBus } from "../../core/commands/CommandBus";

export class WardenBrainSystem implements ISystem {
  readonly phase = SystemPhase.Intents;
  private currentState: IWardenState;
  private states: Map<WardenStateType, IWardenState> = new Map();
  private ctx: AIContext;
  private unsubReset: (() => void) | null = null;

  constructor(
    private refs: EntityRefs,
    private ai: ComponentStore<WardenAIComponent>,
    private transforms: ComponentStore<TransformComponent>,
    private wardenTraversal: ComponentStore<WardenTraversalComponent>,
    private healths: ComponentStore<HealthComponent>,
    private broker: EventBroker,
    private commands: CommandBus
  ) {
    this.states.set("DORMANT", new WardenDormantState());
    this.states.set("HUNTING", new WardenHuntingState());
    this.states.set("CHARGE_PREP", new WardenChargePrepState());
    this.states.set("CHARGE_ATTACK", new WardenChargeAttackState());
    this.states.set("RECOVERY", new WardenRecoveryState());
    this.states.set("FAKE_DEATH", new WardenFakeDeathState());
    this.states.set("FINAL_PHASE", new WardenFinalPhaseState());

    this.currentState = this.states.get("DORMANT") as IWardenState;
    this.ctx = { 
      wardenId: -1, 
      playerId: -1, 
      ai: null as any, 
      transforms: this.transforms, 
      wardenTraversal: this.wardenTraversal, 
      healths: this.healths,
      commands: this.commands, 
      broker: this.broker 
    };
  }

  public init(): void {
    this.ctx.wardenId = this.refs.warden;
    this.ctx.playerId = this.refs.player;
    this.ctx.ai = this.ai.get(this.refs.warden)!;
    this.currentState.enter(this.ctx);
    this.broker.publish(GameEvent.WARDEN_STATE_CHANGE, { state: this.currentState.name, hue: this.currentState.hue });

    this.unsubReset = this.broker.subscribe(GameEvent.GAME_RESET, () => {
      this.currentState = this.states.get("DORMANT") as IWardenState;
      this.ctx.ai = this.ai.get(this.refs.warden)!;
      this.currentState.enter(this.ctx);
      this.broker.publish(GameEvent.WARDEN_STATE_CHANGE, { state: this.currentState.name, hue: this.currentState.hue });
    });
  }

  public update(dt: number): void {
    if (!this.ctx.ai) this.ctx.ai = this.ai.get(this.refs.warden)!;

    const wHealth = this.healths.get(this.refs.warden);
    if (wHealth && wHealth.current <= 0 && !this.ctx.ai.hasFakedDeath && this.currentState.type !== "FAKE_DEATH" && this.currentState.type !== "FINAL_PHASE") {
      this.ctx.ai.hasFakedDeath = true;
      this.transitionTo("FAKE_DEATH");
      return;
    }

    const nextStateType = this.currentState.update(this.ctx, dt);
    if (nextStateType && nextStateType !== this.currentState.type) {
      this.transitionTo(nextStateType);
    }
  }

  private transitionTo(nextStateType: WardenStateType): void {
    this.currentState.exit(this.ctx);
    const nextState = this.states.get(nextStateType);
    if (!nextState) throw new Error(`Warden state not found: ${nextStateType}`);
    this.currentState = nextState;
    this.currentState.enter(this.ctx);
    this.ctx.ai.state = this.currentState.name;
    this.ctx.ai.hue = this.currentState.hue;
    this.broker.publish(GameEvent.WARDEN_STATE_CHANGE, { state: this.currentState.name, hue: this.currentState.hue });
  }

  public dispose(): void {
    if (this.unsubReset) this.unsubReset();
  }
}

src/gameplay/systems/WardenTraversalSyst:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { ComponentStore } from "../../core/ecs/ComponentStore";
import { KinematicVelocityComponent, WardenTraversalComponent, TransformComponent, KinematicTargetComponent } from "../../core/ecs/Components";
import { EntityRefs } from "../../core/ecs/EntityRefs";
import { PLATFORM_AABBS, BORDER_AABBS } from "../../physics/collisions/EnvironmentColliders";

export class WardenTraversalSystem implements ISystem {
  readonly phase = SystemPhase.Kinematics;
  private gravity = -22.0;
  private maxFallSpeed = -35.0;

  constructor(
    private refs: EntityRefs,
    private velocities: ComponentStore<KinematicVelocityComponent>,
    private traversal: ComponentStore<WardenTraversalComponent>,
    private transforms: ComponentStore<TransformComponent>,
    private targets: ComponentStore<KinematicTargetComponent>
  ) {}

  public update(dt: number): void {
    const vel = this.velocities.get(this.refs.warden);
    const trav = this.traversal.get(this.refs.warden);
    const trans = this.transforms.get(this.refs.warden);
    const target = this.targets.get(this.refs.warden);
    if (!vel || !trav || !trans || !target) return;

    let resolvedVelX = vel.x;
    let resolvedVelY = vel.y;

    if (!trav.isGrounded && vel.y <= 0.1) {
      trav.velY += this.gravity * dt;
      if (trav.velY < this.maxFallSpeed) trav.velY = this.maxFallSpeed;
      resolvedVelY += trav.velY;
    } else if (trav.isGrounded && vel.y <= 0.1) {
      trav.velY = 0;
    }

    let nextX = trans.x + resolvedVelX * dt;
    let nextY = trans.y + resolvedVelY * dt;

    trav.isGrounded = false;
    trav.isWallClinging = false;
    trav.wallNormalX = 0;

    const wHalfW = 1.0;
    const wHalfH = 1.0;
    const allColliders = [...PLATFORM_AABBS, ...BORDER_AABBS];

    for (const aabb of allColliders) {
      const overlapX = (nextX + wHalfW > aabb.minX) && (nextX - wHalfW < aabb.maxX);
      const overlapY = (nextY + wHalfH > aabb.minY) && (nextY - wHalfH < aabb.maxY);

      if (overlapX && overlapY) {
        const overlapDepthX = Math.min(nextX + wHalfW - aabb.minX, aabb.maxX - (nextX - wHalfW));
        const overlapDepthY = Math.min(nextY + wHalfH - aabb.minY, aabb.maxY - (nextY - wHalfH));

        if (overlapDepthY < overlapDepthX) {
          if (nextY > (aabb.minY + aabb.maxY) / 2) {
            nextY = aabb.maxY + wHalfH;
            trav.isGrounded = true;
            trav.velY = 0;
            resolvedVelY = 0;
          } else {
            nextY = aabb.minY - wHalfH;
            trav.velY = 0;
            resolvedVelY = 0;
          }
        } else {
          if (nextX > (aabb.minX + aabb.maxX) / 2) {
            nextX = aabb.maxX + wHalfW;
            trav.wallNormalX = 1;
          } else {
            nextX = aabb.minX - wHalfW;
            trav.wallNormalX = -1;
          }
          trav.isWallClinging = true;
          resolvedVelX = 0;
        }
      }
    }

    vel.x = resolvedVelX;
    vel.y = resolvedVelY;

    target.x = nextX;
    target.y = nextY;
  }
}

