import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { ComponentStore } from "../../core/ecs/ComponentStore";
import { TetherComponent, KinematicVelocityComponent, KinematicTargetComponent, TraversalStateComponent } from "../../core/ecs/Components";
import { EntityRefs } from "../../core/ecs/EntityRefs";

export class PlayerKinematicsSystem implements ISystem {
  readonly phase = SystemPhase.Kinematics;
  private gravity = -25.0;
  private wallSlideGravity = -4.0;
  private maxFallSpeed = -40.0;

  constructor(
    private refs: EntityRefs,
    private tethers: ComponentStore<TetherComponent>,
    private velocities: ComponentStore<KinematicVelocityComponent>,
    private targets: ComponentStore<KinematicTargetComponent>,
    private traversal: ComponentStore<TraversalStateComponent>
  ) {}

  public update(dt: number): void {
    const tether = this.tethers.get(this.refs.player);
    const vel = this.velocities.get(this.refs.player);
    const target = this.targets.get(this.refs.player);
    const trav = this.traversal.get(this.refs.player);
    if (!tether || !vel || !target || !trav) return;

    let nextX = target.x;
    let nextY = target.y;

    if (tether.isAttached) {
      tether.dynamicVelY += this.gravity * dt;

      const dx = nextX - tether.anchorX;
      const dy = nextY - tether.anchorY;
      const dist = Math.sqrt(dx * dx + dy * dy) || 1;
      const nx = dx / dist;
      const ny = dy / dist;

      const tx = -ny;
      const ty = nx;

      const inputForceMag = vel.x * 2.5; 
      tether.dynamicVelX += tx * inputForceMag * dt;
      tether.dynamicVelY += ty * inputForceMag * dt;

      tether.dynamicVelX *= Math.pow(0.985, dt * 60);
      tether.dynamicVelY *= Math.pow(0.985, dt * 60);

      if (tether.dynamicVelY < this.maxFallSpeed) tether.dynamicVelY = this.maxFallSpeed;

      nextX += tether.dynamicVelX * dt;
      nextY += tether.dynamicVelY * dt;

      const nextDx = nextX - tether.anchorX;
      const nextDy = nextY - tether.anchorY;
      const nextDist = Math.sqrt(nextDx * nextDx + nextDy * nextDy) || 1;

      if (nextDist > tether.maxLength) {
        const nextNx = nextDx / nextDist;
        const nextNy = nextDy / nextDist;
        nextX = tether.anchorX + nextNx * tether.maxLength;
        nextY = tether.anchorY + nextNy * tether.maxLength;

        const dot = tether.dynamicVelX * nextNx + tether.dynamicVelY * nextNy;
        if (dot > 0) {
          tether.dynamicVelX -= dot * nextNx;
          tether.dynamicVelY -= dot * nextNy;
        }
        tether.tension = 1.0;
      } else {
        tether.tension = Math.max(0, nextDist / tether.maxLength);
      }
      tether.currentLength = nextDist;
      trav.state = "AIRBORNE";
      trav.charge = Math.max(0.0, trav.charge - dt * 2.0);
    } else {
      let currentGravity = this.gravity;
      let isWallSliding = false;
      let wallNormalX = 0;

      const pHalfW = 0.4;
      if (nextX <= -15.0 + pHalfW + 0.05) {
        if (tether.dynamicVelY < 0) {
          isWallSliding = true;
          wallNormalX = 1;
        }
      } else if (nextX >= 15.0 - pHalfW - 0.05) {
        if (tether.dynamicVelY < 0) {
          isWallSliding = true;
          wallNormalX = -1;
        }
      }

      if (isWallSliding) {
        currentGravity = this.wallSlideGravity;
        trav.state = "WALL_SLIDING";
        trav.wallNormalX = wallNormalX;
        tether.dynamicVelX = 0;
        trav.charge = Math.min(1.0, trav.charge + dt * 1.5);
      } else {
        trav.state = "AIRBORNE";
        trav.wallNormalX = 0;
        tether.dynamicVelX += vel.x * dt;
        tether.dynamicVelX *= Math.pow(0.95, dt * 60);
        trav.charge = Math.max(0.0, trav.charge - dt * 2.0);
      }

      tether.dynamicVelY += currentGravity * dt;
      if (tether.dynamicVelY < this.maxFallSpeed) tether.dynamicVelY = this.maxFallSpeed;

      nextX += tether.dynamicVelX * dt;
      nextY += tether.dynamicVelY * dt;

      tether.currentLength = 0;
      tether.tension = 0;
    }

    target.x = nextX;
    target.y = nextY;
  }
}

src/physics/rapier/RapierWorldSystem.ts:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase, InitPhase } from "../../contracts/SystemPhase";
import { IReadablePhysics, PhysicsTransform } from "../../contracts/IPhysicsWorld";
import { EventBroker } from "../../core/events/EventBroker";
import { GameEvent } from "../../core/events/GameEvents";
import { CommandBus } from "../../core/commands/CommandBus";
import { ComponentStore } from "../../core/ecs/ComponentStore";
import { TransformComponent, KinematicVelocityComponent, KinematicTargetComponent, TetherComponent } from "../../core/ecs/Components";
import { EntityRefs } from "../../core/ecs/EntityRefs";
import { EntityId } from "../../core/ecs/Entity";
import { SetKinematicVelocityCommand, ApplyImpulseCommand, SetRopeMaxLengthCommand, SetRopeAttachedCommand } from "../commands/PhysicsCommands";
import { PLATFORM_AABBS, BORDER_AABBS } from "../collisions/EnvironmentColliders";

export class RapierWorldSystem implements ISystem, IReadablePhysics {
  readonly phase = SystemPhase.PhysicsStep;
  readonly initPhase = InitPhase.Bootstrap;

  private RAPIER: any = null;
  private world: any = null;
  private rigidBodies = new Map<EntityId, any>();

  constructor(
    private broker: EventBroker,
    private commands: CommandBus,
    private refs: EntityRefs,
    private transforms: ComponentStore<TransformComponent>,
    private velocities: ComponentStore<KinematicVelocityComponent>,
    private targets: ComponentStore<KinematicTargetComponent>,
    private tethers: ComponentStore<TetherComponent>
  ) {}

  public async init(): Promise<void> {
    this.registerCommands();
    try {
      this.RAPIER = await import("@dimforge/rapier3d-compat");
      if (this.RAPIER && typeof this.RAPIER.init === "function") await this.RAPIER.init();

      this.world = new this.RAPIER.World({ x: 0, y: -9.81, z: 0 });

      const allAabbs = [...PLATFORM_AABBS, ...BORDER_AABBS];
      for (const aabb of allAabbs) {
        const hx = (aabb.maxX - aabb.minX) / 2;
        const hy = (aabb.maxY - aabb.minY) / 2;
        const hz = (aabb.maxZ - aabb.minZ) / 2;
        const cx = aabb.minX + hx;
        const cy = aabb.minY + hy;
        const cz = aabb.minZ + hz;

        const body = this.world.createRigidBody(
          this.RAPIER.RigidBodyDesc.fixed().setTranslation(cx, cy, cz)
        );
        this.world.createCollider(
          this.RAPIER.ColliderDesc.cuboid(hx, hy, hz),
          body
        );
      }

      const pBody = this.world.createRigidBody(this.RAPIER.RigidBodyDesc.kinematicPositionBased().setTranslation(0, 10, 0));
      this.rigidBodies.set(this.refs.player, pBody);
      this.world.createCollider(this.RAPIER.ColliderDesc.cuboid(0.4, 0.9, 0.4), pBody);

      const wBody = this.world.createRigidBody(this.RAPIER.RigidBodyDesc.kinematicPositionBased().setTranslation(5, 5, 0));
      this.rigidBodies.set(this.refs.warden, wBody);
      this.world.createCollider(this.RAPIER.ColliderDesc.cuboid(1.0, 1.0, 1.0), wBody);

    } catch (err) {
      console.warn("Failed to initialize Rapier WASM, running fallback virtual physics engine.", err);
    }
  }

  private registerCommands(): void {
    this.commands.register<SetKinematicVelocityCommand>("SET_KINEMATIC_VELOCITY", (cmd) => {
      const vel = this.velocities.get(cmd.entityId);
      if (vel) { vel.x = cmd.x; vel.y = cmd.y; vel.z = cmd.z; }
    });

    this.commands.register<ApplyImpulseCommand>("APPLY_IMPULSE", (cmd) => {
      if (cmd.entityId === this.refs.player) {
        const tether = this.tethers.get(this.refs.player);
        if (tether) { tether.dynamicVelX += cmd.x; tether.dynamicVelY += cmd.y; }
      } else if (this.world) {
        const body = this.rigidBodies.get(cmd.entityId);
        if (body && typeof body.applyImpulse === "function") body.applyImpulse({ x: cmd.x, y: cmd.y, z: cmd.z }, true);
      }
    });

    this.commands.register<SetRopeMaxLengthCommand>("SET_ROPE_MAX_LENGTH", (cmd) => {
      const tether = this.tethers.get(this.refs.player);
      if (tether) tether.maxLength = cmd.length;
    });

    this.commands.register<SetRopeAttachedCommand>("SET_ROPE_ATTACHED", (cmd) => {
      const tether = this.tethers.get(this.refs.player);
      if (tether) tether.isAttached = cmd.attached;
    });
  }

  public update(_dt: number): void {
    this.commands.flush();

    for (const [, curr] of this.transforms.entries()) {
      curr.prevX = curr.x; curr.prevY = curr.y; curr.prevZ = curr.z;
      curr.prevQx = curr.qx; curr.prevQy = curr.qy; curr.prevQz = curr.qz; curr.prevQw = curr.qw;
    }

    const pTarget = this.targets.get(this.refs.player);
    const pBody = this.rigidBodies.get(this.refs.player);
    if (pTarget && pTarget.active && pBody) {
      pBody.setNextKinematicTranslation({ x: pTarget.x, y: pTarget.y, z: pTarget.z });
    }

    const wTarget = this.targets.get(this.refs.warden);
    const wBody = this.rigidBodies.get(this.refs.warden);
    if (wTarget && wTarget.active && wBody) {
      wBody.setNextKinematicTranslation({ x: wTarget.x, y: wTarget.y, z: wTarget.z });
    }

    if (this.world) this.world.step();

    for (const [id, body] of this.rigidBodies.entries()) {
      const t = body.translation();
      const r = body.rotation();
      const curr = this.transforms.get(id);
      if (curr) {
        curr.x = t.x; curr.y = t.y; curr.z = t.z;
        curr.qx = r.x; curr.qy = r.y; curr.qz = r.z; curr.qw = r.w;
      }
    }

    if (!this.world) {
      const pTrans = this.transforms.get(this.refs.player);
      if (pTrans && pTarget) { pTrans.x = pTarget.x; pTrans.y = pTarget.y; }
      const wTrans = this.transforms.get(this.refs.warden);
      const wTargetFallback = this.targets.get(this.refs.warden);
      if (wTrans && wTargetFallback) { wTrans.x = wTargetFallback.x; wTrans.y = wTargetFallback.y; }
    }

    const tether = this.tethers.get(this.refs.player);
    if (tether) {
      this.broker.publish(GameEvent.ROPE_TENSION_CHANGE, { tension: tether.tension });
      this.broker.publish(GameEvent.ROPE_LENGTH_CHANGE, { length: tether.currentLength, maxLength: tether.maxLength });
    }
  }

  public getTransform(id: EntityId): PhysicsTransform | null {
    const t = this.transforms.get(id);
    return t ? { x: t.x, y: t.y, z: t.z, qx: t.qx, qy: t.qy, qz: t.qz, qw: t.qw } : null;
  }

  public getPreviousTransform(id: EntityId): PhysicsTransform | null {
    const t = this.transforms.get(id);
    return t ? { x: t.prevX, y: t.prevY, z: t.prevZ, qx: t.prevQx, qy: t.prevQy, qz: t.prevQz, qw: t.prevQw } : null;
  }
}

src/physics/sync/TransformSyncSystem.ts:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { IVisualRegistry } from "../../contracts/IVisualRegistry";
import { ComponentStore } from "../../core/ecs/ComponentStore";
import { TransformComponent, TraversalStateComponent } from "../../core/ecs/Components";
import { EntityRefs } from "../../core/ecs/EntityRefs";
import * as BABYLON from "@babylonjs/core";

export class TransformSyncSystem implements ISystem {
    readonly phase = SystemPhase.RenderSync;
    private scratchPrevQuat = new BABYLON.Quaternion();
    private scratchCurrQuat = new BABYLON.Quaternion();

    constructor(
        private refs: EntityRefs,
        private transforms: ComponentStore<TransformComponent>, 
        private traversal: ComponentStore<TraversalStateComponent>,
        private visualRegistry: IVisualRegistry
    ) {}

    public update(_dt: number): void {}

    public render(alpha: number): void {
        for (const [id, curr] of this.transforms.entries()) {
            const node = this.visualRegistry.getTransformNode(id);
            if (!node) continue;

            node.position.x = curr.prevX + (curr.x - curr.prevX) * alpha;
            node.position.y = curr.prevY + (curr.y - curr.prevY) * alpha;
            node.position.z = curr.prevZ + (curr.z - curr.prevZ) * alpha;

            this.scratchPrevQuat.set(curr.prevQx, curr.prevQy, curr.prevQz, curr.prevQw);
            this.scratchCurrQuat.set(curr.qx, curr.qy, curr.qz, curr.qw);

            if (!node.rotationQuaternion) {
                node.rotationQuaternion = new BABYLON.Quaternion();
            }

            BABYLON.Quaternion.SlerpToRef(this.scratchPrevQuat, this.scratchCurrQuat, alpha, node.rotationQuaternion);

            if (id === this.refs.player) {
                const trav = this.traversal.get(id);
                if (trav) {
                    const mesh = node as BABYLON.AbstractMesh;
                    if (mesh && mesh.material) {
                        const mat = mesh.material as BABYLON.StandardMaterial;
                        if (mat) {
                            mat.emissiveColor.r = 0.05 + trav.charge * 0.95;
                            mat.emissiveColor.g = 0.15 + trav.charge * 0.85;
                            mat.emissiveColor.b = 0.05;
                        }
                    }
                }
            }
        }
    }
}

src/ui/hud/DomHudSystem.ts:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { EventBroker } from "../../core/events/EventBroker";
import { GameEvent } from "../../core/events/GameEvents";

export class DomHudSystem implements ISystem {
  readonly phase = SystemPhase.RenderSync;
  private unsubscribes: (() => void)[] = [];
  private tensionBar: HTMLElement | null = null;
  private tensionText: HTMLElement | null = null;
  private speedBar: HTMLElement | null = null;
  private speedText: HTMLElement | null = null;
  private hpText: HTMLElement | null = null;
  private hpValue: HTMLElement | null = null;
  private bossStateText: HTMLElement | null = null;
  private bossPhaseText: HTMLElement | null = null;
  private wardenHpBar: HTMLElement | null = null;
  private wardenHpValue: HTMLElement | null = null;
  private overlay: HTMLElement | null = null;
  private overlayTitle: HTMLElement | null = null;

  constructor(private broker: EventBroker) {}

  public init(): void {
    this.cacheDomElements();
    this.registerSubscribers();
  }

  public update(_dt: number): void {}

  private cacheDomElements(): void {
    if (typeof document === "undefined") return;
    this.tensionBar = document.getElementById("tension-meter-bar");
    this.tensionText = document.getElementById("tension-meter-text");
    this.speedBar = document.getElementById("speedometer-bar");
    this.speedText = document.getElementById("speedometer-text");
    this.hpText = document.getElementById("player-hp-bar");
    this.hpValue = document.getElementById("player-hp-value");
    this.bossStateText = document.getElementById("boss-state-text");
    this.bossPhaseText = document.getElementById("boss-state-phase");
    this.wardenHpBar = document.getElementById("warden-hp-bar");
    this.wardenHpValue = document.getElementById("warden-hp-value");
    this.overlay = document.getElementById("game-state-overlay");
    this.overlayTitle = document.getElementById("game-state-title");
  }

  private registerSubscribers(): void {
    this.unsubscribes.push(
      this.broker.subscribe(GameEvent.ROPE_TENSION_CHANGE, (payload) => this.updateTensionDisplay(payload.tension))
    );
    this.unsubscribes.push(
      this.broker.subscribe(GameEvent.PLAYER_VELOCITY_CHANGED, (payload) => this.updateVelocityDisplay(payload.velocity, payload.maxVelocity))
    );
    this.unsubscribes.push(
      this.broker.subscribe(GameEvent.PLAYER_HEALTH_CHANGED, (payload) => this.updateHealthDisplay(payload.hp, payload.maxHp))
    );
    this.unsubscribes.push(
      this.broker.subscribe(GameEvent.WARDEN_STATE_CHANGE, (payload) => this.updateWardenStateDisplay(payload.state, payload.hue))
    );
    this.unsubscribes.push(
      this.broker.subscribe(GameEvent.WARDEN_HEALTH_CHANGED, (payload) => this.updateWardenHealthDisplay(payload.hp, payload.maxHp))
    );
    this.unsubscribes.push(
      this.broker.subscribe(GameEvent.GAME_OVER, () => this.showOverlay("GAME OVER", "#ef4444"))
    );
    this.unsubscribes.push(
      this.broker.subscribe(GameEvent.GAME_WIN, () => this.showOverlay("VICTORY", "#22c55e"))
    );
    this.unsubscribes.push(
      this.broker.subscribe(GameEvent.GAME_RESET, () => this.hideOverlay())
    );
  }

  private updateTensionDisplay(value: number): void {
    const clamped = Math.max(0, Math.min(1, value));
    const percentage = (clamped * 100).toFixed(1) + "%";
    if (this.tensionBar) {
      this.tensionBar.style.width = percentage;
      if (clamped > 0.8) this.tensionBar.style.backgroundColor = "var(--signal-red, #ef4444)";
      else if (clamped > 0.5) this.tensionBar.style.backgroundColor = "var(--signal-yellow, #eab308)";
      else this.tensionBar.style.backgroundColor = "var(--signal-green, #22c55e)";
    }
    if (this.tensionText) this.tensionText.textContent = `TENSION: ${percentage}`;
  }

  private updateVelocityDisplay(velocity: number, maxVelocity: number): void {
    const ratio = maxVelocity > 0 ? Math.max(0, Math.min(1, velocity / maxVelocity)) : 0;
    const percentage = (ratio * 100).toFixed(0) + "%";
    if (this.speedBar) this.speedBar.style.width = percentage;
    if (this.speedText) this.speedText.textContent = `VELOCITY: ${velocity.toFixed(0)} / ${maxVelocity.toFixed(0)} m/s`;
  }

  private updateHealthDisplay(hp: number, maxHp: number): void {
    if (this.hpValue) this.hpValue.textContent = `HP: ${hp} / ${maxHp}`;
    if (this.hpText) {
      const hpPct = ((hp / maxHp) * 100).toFixed(0) + "%";
      this.hpText.style.width = hpPct;
      this.hpText.style.backgroundColor = hp <= 1 ? "var(--signal-red, #ef4444)" : "var(--signal-green, #22c55e)";
    }
  }

  private updateWardenHealthDisplay(hp: number, maxHp: number): void {
    const percentage = maxHp > 0 ? (hp / maxHp) : 0;
    const pctString = (percentage * 100).toFixed(0) + "%";
    if (this.wardenHpValue) {
      this.wardenHpValue.textContent = `HP: ${hp.toFixed(0)} / ${maxHp.toFixed(0)}`;
    }
    if (this.wardenHpBar) {
      this.wardenHpBar.style.width = pctString;
    }
  }

  private updateWardenStateDisplay(state: string, hue: string): void {
    if (this.bossStateText) {
      this.bossStateText.textContent = `WARDEN: ${state.toUpperCase()}`;
      this.bossStateText.style.color = hue;
    }
    if (this.bossPhaseText) {
      this.bossPhaseText.style.borderColor = hue;
      this.bossPhaseText.style.color = hue;
      this.bossPhaseText.textContent = state === "BERSERK OVERDRIVE" ? "FINAL PHASE" : "PHASE 01";
    }
  }

  private showOverlay(title: string, color: string): void {
    if (this.overlay) this.overlay.style.display = "flex";
    if (this.overlayTitle) {
      this.overlayTitle.textContent = title;
      this.overlayTitle.style.color = color;
      this.overlayTitle.style.textShadow = `0 0 20px ${color}80`;
    }
  }

  private hideOverlay(): void {
    if (this.overlay) this.overlay.style.display = "none";
  }

  public dispose(): void {
    this.unsubscribes.forEach((unsub) => unsub());
    this.unsubscribes = [];
  }
}

